const input=$json.body??$json;
const text=String(input.seller_response??input.response_text??input.inbound_message??'').trim();
const amountMatch=text.replace(/[$,]/g,'').match(/(?:^|\s)(?:\$)?(\d{2,8})(?:\.\d{1,2})?(?:\s|$)/);
const amount=amountMatch?Number(amountMatch[1]):null;
const lower=text.toLowerCase();
const dnc=input.dnc===true||/\b(stop|unsubscribe|do not contact|don't contact|remove me)\b/.test(lower);
const accepted=/\b(yes|accept|accepted|deal|agreed|sounds good|let's do it|okay)\b/.test(lower);
const rejected=/\b(no|not interested|pass|decline|declined|no thanks)\b/.test(lower);
const question=/\?| \b(how much|what can you pay|why|when|how does)\b/.test(lower);
let classification='other_response';
if(dnc) classification='dnc';
else if(accepted) classification='accepted';
else if(amount!==null&&/\b(offer|price|pay|counter|take)\b/.test(lower)) classification='counteroffer';
else if(rejected) classification='rejected';
else if(question) classification='question';
else if(!text) classification='no_response';
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao??0);
const nearBand=mao>0&&amount!==null&&amount>mao&&amount<=mao*1.10;
const aboveMao=mao>0&&amount!==null&&amount>mao*1.10;
let status='classified',next='WF-318';
if(dnc){status='blocked_dnc';next='WF-126';}
else if(!text){status='no_response';next='WF-318';}
else if(classification==='accepted'){status='accepted';next='WF-318';}
else if(classification==='counteroffer'){status=aboveMao?'counteroffer_above_mao':nearBand?'counteroffer_near_mao':'counteroffer_within_mao';next=aboveMao?'WF-320':'WF-319';}
else if(classification==='rejected'){status='rejected';next='WF-320';}
else if(classification==='question'||classification==='other_response'){status=classification;next='WF-319';}
return [{json:{...input,workflow_id:'WF-317',workflow_name:'Seller Response → AI Classification & Negotiation Routing',seller_response:text,classification,counteroffer_amount:amount,dynamic_mao:mao,mao_relationship:amount===null?'unknown':aboveMao?'above_110_percent_mao':nearBand?'near_mao':'within_mao',status,next_workflow:next,ai_reasoning:{signals:{accepted,rejected,question,dnc,amount_detected:amount!==null},note:'Classification is deterministic/rules-based here; downstream AI negotiation logic may enrich the decision.',guardrails:{dnc_protection:true,dynamic_mao_protection:mao>0}},crm_activity:{activity_type:'seller_response_classified',deal_id:input.deal_id,lead_id:input.lead_id,property_id:input.property_id,status,classification,counteroffer_amount:amount,reason:'Seller response classified as '+classification}}}];
